css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  margin-top: 0 !important;
  margin-right: 0 !important;
  margin-bottom: 0 !important;
  margin-left: 0 !important;
  padding: 0 !important;
}

.cd-mr * {
  box-sizing: border-box;
}

.cd-mr {
  box-sizing: border-box;
  position: relative;
  width: 210mm;
  height: 297mm;
  overflow: hidden;
  margin: 0;
  padding: 0;
  color: #202020;
  background: #fff;
  font-family: "TH Sarabun Document", "TH SarabunPSK", sans-serif;
  font-size: 4.10mm;
  line-height: 1;
  page-break-after: always;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cd-mr.last-page {
  page-break-after: auto;
}

.cd-mr .document-header {
  position: absolute;
  left: 0;
  top: 0;
  width: 210mm;
  height: 45mm;
}

.cd-mr .company-logo {
  position: absolute;
  left: 12.7mm;
  top: 18.3mm;
  width: 19mm;
  height: 7.3mm;
  object-fit: contain;
}

.cd-mr .company-name {
  position: absolute;
  left: 34.3mm;
  top: 13.4mm;
  width: 96mm;
  overflow: hidden;
  font-size: 6.2mm;
  font-weight: 700;
  line-height: 6.8mm;
  white-space: nowrap;
}

.cd-mr .company-address {
  position: absolute;
  left: 34.3mm;
  top: 22.5mm;
  width: 156mm;
  overflow: hidden;
  font-size: 4mm;
  line-height: 4.6mm;
  white-space: nowrap;
}

.cd-mr .company-contact {
  position: absolute;
  left: 34.3mm;
  top: 28.5mm;
  font-size: 4mm;
  line-height: 4.6mm;
  white-space: nowrap;
}

.cd-mr .company-tax {
  position: absolute;
  left: 34.3mm;
  top: 35mm;
  font-size: 3.6mm;
  line-height: 4.5mm;
  white-space: nowrap;
}

.cd-mr .document-title {
  position: absolute;
  left: 131.5mm;
  top: 37.5mm;
  width: 59mm;
  height: 7mm;
  padding-top: 1.1mm;
  border-radius: 6mm;
  background: #e2a2f5;
  font-size: 5.2mm;
  font-weight: 700;
  line-height: 5.3mm;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
}

.cd-mr .copy-title {
  position: absolute;
  left: 131.5mm;
  top: 45.3mm;
  width: 59mm;
  font-size: 4mm;
  font-weight: 700;
  line-height: 4.5mm;
  text-align: center;
  white-space: nowrap;
}

.cd-mr .request-info {
  position: absolute;
  left: 11mm;
  top: 49mm;
  width: 188mm;
  height: 27mm;
  padding: 3mm;
  border: .24mm solid #202020;
  border-radius: 3mm;
  overflow: hidden;
}

.cd-mr .info-field {
  position: absolute;
  display: block;
  height: 9mm;
  line-height: 4mm;
  overflow: hidden;
  white-space: nowrap;
}

.cd-mr .info-field .label {
  display: inline-block;
  min-width: 25mm;
  color: #5f6368;
  font-size: 3.15mm;
}

.cd-mr .info-field>span:not(.label),
.cd-mr .info-field>strong {
  font-size: 3.85mm;
  font-weight: 400;
}

.cd-mr .info-number {
  left: 3mm;
  top: 3mm;
  width: 47mm;
}

.cd-mr .info-date {
  left: 53mm;
  top: 3mm;
  width: 45mm;
}

.cd-mr .info-required {
  left: 101mm;
  top: 3mm;
  width: 43mm;
}

.cd-mr .info-purpose {
  left: 3mm;
  top: 12mm;
  width: 92mm;
}

.cd-mr .info-warehouse {
  left: 98mm;
  top: 12mm;
  width: 87mm;
}

.cd-mr .info-status {
  left: 3mm;
  top: 21mm;
  width: 92mm;
}

.cd-mr .info-department {
  left: 98mm;
  top: 21mm;
  width: 87mm;
}

.cd-mr .info-requester {
  left: 3mm;
  top: 21mm;
  width: 92mm;
}

.cd-mr .document-main {
  position: absolute;
  left: 11mm;
  top: 80mm;
  width: 188mm;
  height: 203mm;
  border: .24mm solid #202020;
  border-radius: 3mm;
  overflow: hidden;
  background: #fff;
}

.cd-mr .items-table {
  width: 100%;
  height: 151mm;
  table-layout: fixed;
  border-collapse: collapse;
  border-spacing: 0;
}

.cd-mr .items-table .col-no {
  width: 8%;
}

.cd-mr .items-table .col-item {
  width: 45%;
}

.cd-mr .items-table .col-warehouse {
  width: 22%;
}

.cd-mr .items-table .col-qty {
  width: 13%;
}

.cd-mr .items-table .col-required {
  width: 12%;
}

.cd-mr .items-table th,
.cd-mr .items-table td {
  border: 0;
  border-right: .24mm solid #202020;
  padding: 0;
  vertical-align: top;
  overflow: hidden;
}

.cd-mr .items-table th:last-child,
.cd-mr .items-table td:last-child {
  border-right: 0;
}

.cd-mr .items-table thead tr {
  height: 10mm;
}

.cd-mr .items-table thead th {
  padding-top: 1.2mm;
  background: #d6d6d6;
  border-bottom: .24mm solid #202020;
  text-align: center;
  vertical-align: middle;
  font-size: 3.85mm;
  line-height: 3.5mm;
  font-weight: 700;
  white-space: nowrap;
}

.cd-mr .items-table thead small {
  font-size: 2.55mm;
  font-weight: 400;
}

.cd-mr .items-table tbody {
  height: 141mm;
}

.cd-mr .items-table tbody td {
  font-size: 3.9mm;
  line-height: 4.25mm;
}

.cd-mr .cell-no {
  padding: 2.3mm 1.8mm 0 !important;
  text-align: right;
}

.cd-mr .cell-item {
  padding: 2mm 1.7mm 0 !important;
}

.cd-mr .cell-warehouse {
  padding: 2mm 1.2mm 0 !important;
  font-size: 3.45mm !important;
  white-space: normal;
  word-break: break-word;
}

.cd-mr .cell-qty {
  padding: 2mm .9mm 0 !important;
  text-align: right;
  white-space: nowrap;
}

.cd-mr .cell-required {
  padding: 2mm .9mm 0 !important;
  text-align: center;
  font-size: 3.25mm;
  white-space: nowrap;
}

.cd-mr .item-main {
  line-height: 4.25mm;
  overflow: hidden;
  white-space: normal;
  word-break: break-word;
}

.cd-mr .item-meta {
  margin-top: .65mm;
  color: #5f6368;
  font-size: 3mm;
  line-height: 3.3mm;
  white-space: normal;
}

.cd-mr .items-table .fill-row {
  height: auto;
}

.cd-mr .items-table .fill-row td {
  padding: 0 !important;
}

.cd-mr .summary-section {
  position: relative;
  display: block;
  width: 100%;
  height: 20mm;
  border-top: .24mm solid #202020;
  overflow: hidden;
}

.cd-mr .remark-box {
  position: absolute;
  left: 0;
  top: 0;
  width: 60%;
  height: 100%;
  padding: 2.6mm 3mm;
  border-right: .24mm solid #202020;
  overflow: hidden;
}

.cd-mr .summary-label {
  font-size: 3.65mm;
  font-weight: 700;
  line-height: 4mm;
}

.cd-mr .remark-text {
  margin-top: 1.5mm;
  font-size: 3.45mm;
  line-height: 4mm;
  overflow: hidden;
  max-height: 11mm;
}

.cd-mr .totals-box {
  position: absolute;
  left: 60%;
  top: 0;
  width: 40%;
  height: 100%;
}

.cd-mr .total-row {
  position: relative;
  width: 100%;
  height: 10mm;
  font-size: 3.4mm;
  line-height: 10mm;
  overflow: hidden;
}

.cd-mr .total-row span {
  position: absolute;
  left: 2.5mm;
  right: 19mm;
  top: 0;
}

.cd-mr .total-row strong {
  position: absolute;
  right: 2mm;
  top: 0;
  width: 17mm;
  text-align: right;
  font-size: 3.7mm;
  font-weight: 400;
}

.cd-mr .grand-total-row {
  border-top: .24mm solid #202020;
  font-weight: 700;
}

.cd-mr .signature-section {
  position: relative;
  display: block;
  width: 100%;
  height: 32mm;
  border-top: .24mm solid #202020;
  overflow: hidden;
}

.cd-mr .signature-block {
  position: absolute;
  top: 0;
  width: 33.333333%;
  height: 100%;
  margin: 0;
  padding: 0;
  border-right: .24mm solid #202020;
  text-align: center;
  overflow: hidden;
}

.cd-mr .signature-block:nth-child(1) {
  left: 0;
}

.cd-mr .signature-block:nth-child(2) {
  left: 33.333333%;
}

.cd-mr .signature-block:nth-child(3) {
  left: 66.666666%;
  border-right: 0;
}

.cd-mr .signature-title {
  position: absolute;
  left: 1mm;
  right: 1mm;
  top: 17mm;
  width: auto;
  height: 5mm;
  overflow: visible;
  font-size: 2.85mm;
  line-height: 3.05mm;
  text-align: center;
  white-space: nowrap;
}

.cd-mr .signature-role {
  display: inline;
  margin-left: .7mm;
  font-size: 2.65mm;
  line-height: 3.05mm;
  white-space: nowrap;
}

.cd-mr .signature-date {
  position: absolute;
  right: 1mm;
  top: 3.5mm;
  width: 23mm;
  height: 10.5mm;
  overflow: hidden;
  font-size: 3.15mm;
  line-height: 3.45mm;
  text-align: center;
  white-space: nowrap;
}

.cd-mr .signature-date-caption {
  position: absolute;
  right: 1mm;
  top: 17mm;
  width: 23mm;
  height: 5mm;
  overflow: hidden;
  font-size: 2.85mm;
  line-height: 3.05mm;
  text-align: center;
  white-space: nowrap;
}

.cd-mr .signature-placeholder {
  display: block !important;
  width: 36mm !important;
  height: 0 !important;
  min-height: 0 !important;
  margin: 5.25mm auto 0 !important;
  border: 0 !important;
  border-bottom: .24mm solid #202020 !important;
  background: none !important;
}

@media print {
  .cd-mr {
    margin: 0 !important;
    box-shadow: none !important;
  }
}

.cd-mr .signature-line {
  position: absolute;
  left: 50%;
  top: 3.5mm;
  width: 40mm;
  height: 10.5mm;
  margin: 0;
  transform: translateX(-50%);
  display: block;
  overflow: visible;
  background: none;
  border: 0 !important;
}

.cd-mr .action-signature-image {
  display: block !important;
  width: 36mm !important;
  height: 10.5mm !important;
  max-width: 36mm !important;
  max-height: 10.5mm !important;
  margin: 0 !important;
  transform: scale(1) !important;
  transform-origin: center center !important;
  position: relative !important;
  z-index: 2 !important;
  border: 0 !important;
  object-fit: contain !important;
}

@media print {
  .print-format-gutter {
    padding: 0 !important;
  }

  .action-banner {
    display: none !important;
  }
}
